    const entries = Object.entries(groups);
    return card('Arm AI Orchestrator', `<div class="se-scheduler">${entries.map(([k,v])=>`<div class="se-scheduler-state"><span>${k}</span><strong>${v.length}</strong></div>`).join('')}</div><div class="se-job-list">${entries.flatMap(([k,v])=>v.slice(0,2).map((job,idx)=>`<div class="se-job"><i class="se-job-dot ${k.toLowerCase()}"></i><div><div class="se-job-name">${esc(job)}</div><div class="se-job-reason">${k==='Running'?'Tier-A/EDF admitted':k==='Sleeping'?'Wake/sleep policy':k==='Deferred'?'Lower criticality; within max deferral':'Bounded queue'}</div></div><span class="se-job-time">${idx?'+40 ms':'now'}</span></div>`)).join('')}</div><p class="se-help">Reserved earthquake capacity, bounded queues, forced wildfire scans, maximum deferral, and fail-visible overload are exercised by the deterministic scenario.</p>`, pill(runtime.overloaded?'OVERLOAD':'SCHEDULER HEALTHY',runtime.overloaded?'danger':'success'));
